export default async function dates({ scheduledAt, calendarId }) {
  const d = new Date(scheduledAt);
  if (!Number.isFinite(d.getTime()) || !calendarId || calendarId.includes("YOUR_"))
    throw Error("Configure calendar and schedule");
  const day = d.toISOString().slice(0, 10);
  return {
    calendarId,
    day,
    timeMin: day + "T00:00:00.000Z",
    timeMax: new Date(Date.parse(day + "T00:00:00Z") + 86400000).toISOString(),
  };
}

