export default async function collect({ items, nextPageToken, previous, day }) {
  if (!Array.isArray(items)) throw Error("Invalid Calendar page");
  const s = previous ?? { events: [], tokens: [] };
  if (!Array.isArray(s.events) || !Array.isArray(s.tokens))
    throw Error("Invalid Calendar progress");
  const events = [
    ...s.events,
    ...items.map((e) => ({
      id: e.id,
      title: e.summary ?? "",
      start: e.start ?? null,
      end: e.end ?? null,
      attendees: (e.attendees ?? []).map((a) => ({
        name: a.displayName ?? "",
        email: a.email ?? "",
        response: a.responseStatus ?? "",
      })),
    })),
  ];
  if (events.length > 5000) throw Error("Too many meetings for one summary");
  const token = nextPageToken ?? null;
  if (token !== null && (typeof token !== "string" || !token || s.tokens.includes(token)))
    throw Error("Invalid Calendar page token");
  return {
    state: { events, tokens: token ? [...s.tokens, token] : s.tokens },
    pageToken: token,
    more: token !== null,
    facts: JSON.stringify({ day, events }),
  };
}

