export default async function reserve({ day, text, channel, acknowledge, resolution }, ctx) {
  if (!channel || channel.includes("YOUR_") || !text)
    throw Error("Configure Slack channel and summary");
  const key = "daily-meetings:" + day,
    s = await ctx.state.get(key);
  if (s?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending Slack message " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { key, text, channel, send: false };
    }
  }
  if (s?.status === "done") return { key, text, channel, send: false };
  await ctx.state.set(key, { status: "pending" });
  return { key, text, channel, send: true };
}

